<x-layout title="Detail Lamaran"><div class="pagehead"><div><p class="eyebrow">{{ $application->event->title }}</p><h1>{{ $application->position->name }}</h1><p>{{ $application->snapshot['name']??$application->volunteer->name }}</p></div><x-badge :status="$application->status"/></div><div class="grid two"><section class="card"><h2>Hasil kecocokan</h2>@if($application->match_score!==null)<div class="kpi">{{ number_format($application->match_score,2,',','.') }}<span class="hint"> /100</span></div><p class="hint">Penerimaan tetap ditentukan Organizer.</p><table><thead><tr><th>Komponen</th><th>Nilai</th><th>Bobot</th></tr></thead><tbody><tr><td>Skill</td><td>{{ $application->skill_score }}</td><td>50%</td></tr><tr><td>Ketersediaan</td><td>{{ $application->availability_score }}</td><td>30%</td></tr><tr><td>Lokasi</td><td>{{ $application->location_score }}</td><td>20%</td></tr></tbody></table>@else<p class="muted">Skor tersedia setelah screening dokumen selesai.</p>@endif<p style="margin-top:16px">Nilai assessment: <strong>{{ $application->assessment_score??'Belum tersedia' }}</strong></p>@foreach($application->screening??[] as $reason)<p class="error">{{ $reason }}</p>@endforeach @if($application->decision_note)<p>Catatan seleksi: {{ $application->decision_note }}</p>@endif</section><section class="card"><h2>Profil lamaran</h2><p>Kota: {{ $application->snapshot['city']??$application->volunteer->city }}</p><p>{{ $application->snapshot['bio']??$application->volunteer->bio }}</p><p class="hint">{{ $application->submitted_at?'Data profil disimpan saat pengiriman.':'Lengkapi profil sebelum mengirim lamaran.' }}</p>@if(auth()->id()===$application->volunteer_id)<a href="{{ route('volunteer.profile') }}">Kelola Profil →</a>@endif</section></div>
<section class="card" style="margin-top:24px"><h2>Dokumen</h2><p class="hint">CV PDF; dokumen pendukung PDF/JPG/PNG. Maksimal 5 MB/file dan 5 file/lamaran. Hanya pemilik dan perekrut event terkait yang dapat mengunduh file siap.</p>@forelse($application->documents as $d)<div class="row" style="padding:14px 0;border-bottom:1px solid #e2e8f0"><div><strong>{{ $d->original_name }}</strong><p class="hint">{{ round($d->size/1024) }} KB · {{ $d->kind }}</p><x-badge :status="$d->status"/></div><div class="actions">@can('download',$d)<a class="btn secondary" href="{{ route('document.download',$d) }}">Unduh</a>@endcan @if(auth()->id()===$application->volunteer_id && in_array($application->status,['draft','documents_pending']))@if($d->status==='scan_failed')<form method="post" action="{{ route('document.retry',$d) }}">@csrf<button class="btn secondary">Periksa Lagi</button></form>@endif @if($application->status==='draft'||in_array($d->status,['scan_failed','rejected']))<form method="post" action="{{ route('document.delete',$d) }}" data-confirm="Hapus dokumen ini?">@csrf @method('delete')<button class="btn secondary">Hapus</button></form>@endif @endif</div></div>@empty<p class="empty">Belum ada dokumen.</p>@endforelse
