@if(auth()->id()===$application->volunteer_id)<section class="card" style="margin-top:24px"><h2>Tindakan berikutnya</h2><div class="actions">@if($application->status==='draft')<form method="post" action="{{ route('application.submit',$application) }}" data-confirm="Kirim lamaran dan bagikan dokumen kepada perekrut event ini?">@csrf<button class="btn">Tinjau & Kirim Lamaran</button></form>@elseif($application->status==='assessment_pending')@if($application->attempt)<a class="btn" href="{{ route('assessment.show',$application) }}">Lanjutkan Assessment</a>@else<form method="post" action="{{ route('assessment.start',$application) }}" data-confirm="Timer akan dimulai. Satu percobaan saja. Mulai assessment?">@csrf<p>{{ $application->position->duration_minutes }} menit · {{ count($application->position->questions) }} soal · satu percobaan.</p><button class="btn">Mulai Assessment</button></form>@endif @elseif($application->status==='documents_pending')<p>Pemeriksaan dokumen belum selesai. Perbarui halaman setelah beberapa saat atau unggah ulang file yang ditolak.</p>@else<p>Status lamaran: <x-badge :status="$application->status"/></p>@endif
